#include <bits/stdc++.h>
using namespace std;

double findMedianSortedArrays(vector<int>& a, vector<int>& b) {
    if (a.size() > b.size()) swap(a, b);           // always binary search the smaller array
    int m = a.size(), n = b.size();
    int lo = 0, hi = m;
    int half = (m + n + 1) / 2;
    while (lo <= hi) {
        int i = (lo + hi) / 2;
        int j = half - i;
        double left1 = i == 0 ? -1e18 : a[i - 1];
        double right1 = i == m ? 1e18 : a[i];
        double left2 = j == 0 ? -1e18 : b[j - 1];
        double right2 = j == n ? 1e18 : b[j];
        if (left1 <= right2 && left2 <= right1) {          // valid partition found
            if ((m + n) % 2 == 1) return max(left1, left2);
            return (max(left1, left2) + min(right1, right2)) / 2.0;
        } else if (left1 > right2) {
            hi = i - 1;                                        // shrink the partition in nums1
        } else {
            lo = i + 1;                                         // grow the partition in nums1
        }
    }
    return 0;
}
